'use strict';
// Dev tool: bundles the pure overlay modules for the browser settings page.
const fs = require('fs');
const path = require('path');
const names = ['codes', 'templates', 'overlaycfg', 'overlay'];
let out = '/* generated by scripts/build-ui-bundle.js - do not edit */\n(function (g) {\nvar __m = {};\nfunction __def(n, fn) { __m[n] = { fn: fn, exports: {}, done: false }; }\nfunction __req(p) { var n = p.replace("./", ""); var m = __m[n]; if (!m.done) { m.done = true; m.fn(m, m.exports, __req); } return m.exports; }\n';
for (const n of names) {
  const src = fs.readFileSync(path.join(__dirname, '..', 'lib', n + '.js'), 'utf8');
  out += `__def(${JSON.stringify(n)}, function (module, exports, require) {\n${src}\n});\n`;
}
out += 'g.WindyOverlay = { render: __req("overlay").render, normalizeOverlay: __req("overlaycfg").normalizeOverlay, TEMPLATES: __req("templates").TEMPLATES, TEMPLATE_IDS: __req("templates").TEMPLATE_IDS, POSITIONS: __req("overlaycfg").POSITIONS };\n})(window);\n';
fs.writeFileSync(path.join(__dirname, '..', 'homebridge-ui', 'public', 'overlay.bundle.js'), out);
console.log('bundle written', out.length);
